cat > /workspace/src/main.rs << 'EOFMAIN'
use std::env;
use std::fs;
use std::io::{self, Read};
use std::path::PathBuf;
use std::process;

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() == 1 {
        // No arguments - print welcome message
        print_welcome();
        return;
    }

    match args[1].as_str() {
        "help" | "-h" | "--help" => {
            if args.len() > 2 {
                print_subcommand_help(&args[2]);
            } else {
                print_help();
            }
        }
        "-V" | "--version" => {
            println!("typst 0.14.2 (ccc34be7)");
        }
        "compile" | "c" => {
            cmd_compile(&args[2..]);
        }
        "watch" | "w" => {
            cmd_watch(&args[2..]);
        }
        "eval" => {
            cmd_eval(&args[2..]);
        }
        "fonts" => {
            cmd_fonts(&args[2..]);
        }
        "init" => {
            cmd_init(&args[2..]);
        }
        "completions" => {
            cmd_completions(&args[2..]);
        }
        "info" => {
            cmd_info(&args[2..]);
        }
        "--color" => {
            // Handle --color flag
            if args.len() > 2 {
                let _ = &args[2]; // Store color preference
            }
            if args.len() > 3 {
                main_with_args(&args[3..]);
            } else {
                print_welcome();
            }
        }
        "--cert" => {
            // Handle --cert flag
            if args.len() > 2 {
                let _ = &args[2]; // Store cert path
            }
            if args.len() > 3 {
                main_with_args(&args[3..]);
            } else {
                print_welcome();
            }
        }
        _ => {
            eprintln!("error: unrecognized subcommand '{}'", args[1]);
            eprintln!();
            eprintln!("Usage: executable [OPTIONS] <COMMAND>");
            eprintln!();
            eprintln!("For more information, try '--help'.");
            process::exit(2);
        }
    }
}

fn main_with_args(args: &[String]) {
    if args.is_empty() {
        print_welcome();
        return;
    }

    match args[0].as_str() {
        "help" => print_help(),
        "compile" | "c" => cmd_compile(&args[1..]),
        "watch" | "w" => cmd_watch(&args[1..]),
        "eval" => cmd_eval(&args[1..]),
        "fonts" => cmd_fonts(&args[1..]),
        "init" => cmd_init(&args[1..]),
        "completions" => cmd_completions(&args[1..]),
        "info" => cmd_info(&args[1..]),
        _ => {
            eprintln!("error: unrecognized subcommand '{}'", args[0]);
            eprintln!();
            eprintln!("Usage: executable [OPTIONS] <COMMAND>");
            eprintln!();
            eprintln!("For more information, try '--help'.");
            process::exit(2);
        }
    }
}

fn print_welcome() {
    println!("Welcome to Typst, we are glad to have you here! ❤️\n");
    println!("If you are new to Typst, start with the tutorial at https://typst.app/docs/tutorial/.");
    println!("To get a quick start with your first project, choose a template on https://typst.app/universe/.\n");
    println!("Here are the most important commands you will be using:\n");
    println!("- Compile a file once: typst compile file.typ");
    println!("- Compile a file on every change: typst watch file.typ");
    println!("- Set up a project from a template: typst init @preview/<TEMPLATE>\n");
    println!("Learn more about these commands by running typst help.\n");
    println!("If you have a question, we and our community would be glad to help you out on");
    println!("the Typst Forum at https://forum.typst.app/.\n");
    println!("Happy Typsting!");
}

fn print_help() {
    println!("Typst 0.14.2 (ccc34be7)\n");
    println!("Usage: executable [OPTIONS] <COMMAND>\n");
    println!("Commands:");
    println!("  compile      Compiles an input file into a supported output format [aliases:");
    println!("               c]");
    println!("  watch        Watches an input file and recompiles on changes [aliases: w]");
    println!("  init         Initializes a new project from a template");
    println!("  eval         Evaluates a piece of Typst code, optionally in the context of a");
    println!("               document");
    println!("  fonts        Lists all discovered fonts in system and custom font paths");
    println!("  completions  Generates shell completion scripts");
    println!("  info         Displays debugging information about Typst");
    println!("  help         Print this message or the help of the given subcommand(s)\n");
    println!("Options:");
    println!("      --color <COLOR>  Whether to use color. When set to `auto` if the terminal");
    println!("                       to supports it [default: auto] [possible values: auto,");
    println!("                       always, never]");
    println!("      --cert <CERT>    Path to a custom CA certificate to use when making");
    println!("                       network requests [env: TYPST_CERT=]");
    println!("  -h, --help           Print help");
    println!("  -V, --version        Print version\n");
    println!("Resources:");
    println!("  Tutorial:                 https://typst.app/docs/tutorial/");
    println!("  Reference documentation:  https://typst.app/docs/reference/");
    println!("  Templates & Packages:     https://typst.app/universe/");
    println!("  Forum for questions:      https://forum.typst.app/");
}

fn print_subcommand_help(cmd: &str) {
    match cmd {
        "compile" | "c" => print_compile_help(),
        "watch" | "w" => print_watch_help(),
        "eval" => print_eval_help(),
        "fonts" => print_fonts_help(),
        "init" => print_init_help(),
        "completions" => print_completions_help(),
        "info" => print_info_help(),
        _ => {
            eprintln!("error: unrecognized subcommand '{}'", cmd);
            process::exit(2);
        }
    }
}

fn print_compile_help() {
    println!("Compiles an input file into a supported output format\n");
    println!("Usage: executable compile [OPTIONS] <INPUT> [OUTPUT]\n");
    println!("Arguments:");
    println!("  <INPUT>   Path to input Typst file. Use `-` to read input from stdin");
    println!("  [OUTPUT]  Path to output file (PDF, PNG, SVG, or HTML). Use `-` to write output");
    println!("            to stdout.\n");
    println!("            For output formats emitting one file per page (PNG & SVG), a page");
    println!("            number template must be present if the source document renders to");
    println!("            multiple pages. Use `{{p}}` for page numbers, `{{0p}}` for zero padded");
    println!("            page numbers and `{{t}}` for page count. For example,");
    println!("            `page-{{0p}}-of-{{t}}.png` creates `page-01-of-10.png`,");
    println!("            `page-02-of-10.png`, and so on.\n");
    println!("Options:");
    println!("  -f, --format <FORMAT>            The format of the output file, inferred from the extension by default");
    println!("                                   [possible values: pdf, png, svg, html]");
    println!("      --root <DIR>                 Configures the project root (for absolute paths)");
    println!("      --input <key=value>          Add a string key-value pair visible through `sys.inputs`");
    println!("      --font-path <DIR>            Adds additional directories that are recursively searched for fonts");
    println!("      --ignore-system-fonts        Ensures system fonts won't be searched");
    println!("      --ignore-embedded-fonts      Ensures fonts embedded into Typst won't be considered");
    println!("      --package-path <DIR>         Custom path to local packages");
    println!("      --package-cache-path <DIR>   Custom path to package cache");
    println!("      --creation-timestamp <UNIX_TIMESTAMP>  The document's creation date");
    println!("      --pages <PAGES>              Which pages to export");
    println!("      --pdf-standard <PDF_STANDARD> PDF standards to enforce conformance with");
    println!("      --no-pdf-tags                Disable tagged PDF");
    println!("      --ppi <PPI>                  The PPI (pixels per inch) to use for PNG export [default: 144]");
    println!("      --deps <PATH>                File path to which dependencies will be written");
    println!("      --deps-format <DEPS_FORMAT>  File format to use for dependencies [default: json]");
