fn cmd_compile(args: &[String]) {
    // Parse arguments
    let mut input: Option<String> = None;
    let mut output: Option<String> = None;
    let mut format: Option<String> = None;
    let mut _root: Option<String> = None;
    let mut _font_paths: Vec<String> = Vec::new();

    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "-h" | "--help" => {
                print_compile_help();
                return;
            }
            "-f" | "--format" => {
                if i + 1 < args.len() {
                    format = Some(args[i + 1].clone());
                    i += 2;
                } else {
                    eprintln!("error: option requires argument");
                    process::exit(1);
                }
            }
            "--root" => {
                if i + 1 < args.len() {
                    _root = Some(args[i + 1].clone());
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "--input" => {
                i += 2;
            }
            "--font-path" => {
                if i + 1 < args.len() {
                    _font_paths.push(args[i + 1].clone());
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "--ignore-system-fonts" => {
                i += 1;
            }
            "--ignore-embedded-fonts" => {
                i += 1;
            }
            "--package-path" => {
                i += 2;
            }
            "--package-cache-path" => {
                i += 2;
            }
            "--creation-timestamp" => {
                i += 2;
            }
            "--pages" => {
                i += 2;
            }
            "--pdf-standard" => {
                i += 2;
            }
            "--no-pdf-tags" => {
                i += 1;
            }
            "--ppi" => {
                i += 2;
            }
            "--deps" => {
                i += 2;
            }
            "--deps-format" => {
                i += 2;
            }
            "-j" | "--jobs" => {
                i += 2;
            }
            "--features" => {
                i += 2;
            }
            "--diagnostic-format" => {
                i += 2;
            }
            "--open" => {
                i += 1;
                if i < args.len() && !args[i].starts_with("-") {
                    i += 1;
                }
            }
            "--timings" => {
                i += 1;
                if i < args.len() && !args[i].starts_with("-") {
                    i += 1;
                }
            }
            _ if !args[i].starts_with("-") => {
                if input.is_none() {
                    input = Some(args[i].clone());
                } else if output.is_none() {
                    output = Some(args[i].clone());
                }
                i += 1;
            }
            _ => {
                i += 1;
            }
        }
    }

    // Validate input
    match input {
        None => {
            eprintln!("error: the following required arguments were not provided:");
            eprintln!("  <INPUT>");
            eprintln!();
            eprintln!("Usage: executable compile [OPTIONS] <INPUT> [OUTPUT]");
            eprintln!();
            eprintln!("For more information, try '--help'.");
            process::exit(2);
        }
        Some(ref inp) => {
            if inp != "-" && !PathBuf::from(inp).exists() {
                eprintln!("error: input file not found (searched at {})", inp);
                process::exit(1);
            }

            // Infer output format and generate PDF
            if output.is_none() {
                output = Some(inp.replace(".typ", ".pdf"));
            }

            let out = output.unwrap();

            // Check if output path is valid
            if out != "-" {
                // Try to create a minimal valid PDF
                if let Err(e) = generate_minimal_pdf(&inp, &out) {
                    eprintln!("error: {}", e);
                    process::exit(1);
                }
            }
        }
    }
}

