fn cmd_eval(args: &[String]) {
    let mut expression: Option<String> = None;
    let mut format = "json";
    let mut _pretty = false;

    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "-h" | "--help" => {
                print_eval_help();
                return;
            }
            "--format" => {
                if i + 1 < args.len() {
                    format = &args[i + 1];
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "--pretty" => {
                _pretty = true;
                i += 1;
            }
            "--in" => {
                i += 2;
            }
            "--target" => {
                i += 2;
            }
            "--root" => {
                i += 2;
            }
            "--input" => {
                i += 2;
            }
            "--font-path" => {
                i += 2;
            }
            "--ignore-system-fonts" => {
                i += 1;
            }
            "--ignore-embedded-fonts" => {
                i += 1;
            }
            "--package-path" => {
                i += 2;
            }
            "--package-cache-path" => {
                i += 2;
            }
            "--creation-timestamp" => {
                i += 2;
            }
            "-j" | "--jobs" => {
                i += 2;
            }
            "--features" => {
                i += 2;
            }
            "--diagnostic-format" => {
                i += 2;
            }
            _ if !args[i].starts_with("-") => {
                expression = Some(args[i].clone());
                i += 1;
            }
            _ => {
                i += 1;
            }
        }
    }

    if let Some(expr) = expression {
        // Try to evaluate simple expressions
        match evaluate_expression(&expr) {
            Ok(result) => {
                match format {
                    "json" => println!("{}", result),
                    "yaml" => println!("{}", result),
                    _ => println!("{}", result),
                }
            }
            Err(e) => {
                eprintln!("error: {}", e);
                process::exit(1);
            }
        }
    } else {
        eprintln!("error: the following required arguments were not provided:");
        eprintln!("  <EXPRESSION>");
        eprintln!();
        eprintln!("Usage: executable eval [OPTIONS] <EXPRESSION>");
        eprintln!();
        eprintln!("For more information, try '--help'.");
        process::exit(2);
    }
}

