fn cmd_completions(args: &[String]) {
    if args.is_empty() {
        eprintln!("error: the following required arguments were not provided:");
        eprintln!("  <SHELL>");
        eprintln!();
        eprintln!("Usage: executable completions <SHELL>");
        eprintln!();
        eprintln!("For more information, try '--help'.");
        process::exit(2);
    }

    let shell = &args[0];
    match shell.as_str() {
        "-h" | "--help" => print_completions_help(),
        "bash" => {
            println!("_typst() {{");
            println!("    local i cur prev opts cmd");
            println!("    COMPREPLY=()");
            println!("    cur=\"${{COMP_WORDS[COMP_CWORD]}}\"");
            println!("    prev=\"${{COMP_WORDS[COMP_CWORD-1]}}\"");
            println!("    cmd=\"\"");
            println!("    opts=\"\"\n");
            println!("    for i in ${{COMP_WORDS[@]}}");
            println!("    do");
            println!("        case \"${{cmd}},${{i}}\" in");
            println!("            \",$1\")");
            println!("                cmd=\"typst\"");
            println!("                ;;");
            println!("            typst,c)");
            println!("                cmd=\"typst__compile\"");
            println!("                ;;");
            println!("            typst,compile)");
            println!("                cmd=\"typst__compile\"");
            println!("                ;;");
            println!("            *)");
            println!("                ;;");
            println!("        esac");
            println!("    done");
            println!("}}");
            println!("complete -F _typst typst");
        }
        "fish" => {
            println!("# Typst completions for fish");
        }
        "zsh" => {
            println!("# Typst completions for zsh");
        }
        "elvish" => {
            println!("# Typst completions for elvish");
        }
        "powershell" => {
            println!("# Typst completions for powershell");
        }
        _ => {
            eprintln!("error: invalid shell: {}", shell);
            process::exit(1);
        }
    }
}

