fn evaluate_expression(expr: &str) -> Result<String, String> {
    // Very simple expression evaluator for basic math
    let expr = expr.trim();

    // Handle simple addition
    if expr.contains("+") && !expr.contains("\"") {
        let parts: Vec<&str> = expr.split("+").collect();
        if parts.len() == 2 {
            if let (Ok(a), Ok(b)) = (parts[0].trim().parse::<i64>(), parts[1].trim().parse::<i64>()) {
                return Ok((a + b).to_string());
            }
        }
    }

    // Handle simple numbers
    if let Ok(num) = expr.parse::<i64>() {
        return Ok(num.to_string());
    }

    // Handle strings
    if expr.starts_with("\"") && expr.ends_with("\"") {
        return Ok(expr.to_string());
    }

    Err(format!("unable to evaluate expression: {}", expr))
}
